insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('d-the-fertility-class', 'The Fertility Class Exercise Method', 'The Fertility Class', 'fertility', 'digital', 'An online, on-demand movement program for cycle health and fertility, built on the Aviva Method, an exercise system developed by Hungarian physiotherapist Aviva Steiner, per the brand. Classes are 20 to 30 minutes, need no equipment and are organized by cycle phase (follicular, ovulatory, luteal, menstrual) and by goal: preparing to conceive, IVF preparation, cycle regulation. Membership includes the class library, a Foundations series, a one-on-one onboarding call with a certified instructor, an IVF and IUI protocol, and a private community. Founded by certified Aviva Method teachers Zsofia Jamieson and Marta Han.', '$45/month (7-day free trial, cancel anytime; HSA/FSA reimbursable through Flex, per the brand)', '/products/fertility-class/class-movement.webp', 'https://thefertilityclass.com/', '["fertility","irregular","pcos","cramps","fitness"]'::jsonb, '["fertility"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Exercise and education program; not a medical device.","materials":"N/A","recalls":"N/A","sideEffects":"The brand says the program is not recommended for people with a spinal hernia, menorrhagia (extremely heavy bleeding), active malignant tumors, uncontrolled prolapse or recent abdominal surgery (without clearance), or an IUD currently in place, and requires a one-on-one session first for anyone with an endometriosis diagnosis.","opinionAlerts":"The fertility, hormone and blood-flow benefits on the brand''s site are the brand''s claims. The published studies of the Aviva Method looked at period pain, not fertility."}'::jsonb, 'Per The Fertility Class, its advisory board includes reproductive endocrinologist Dr. Katherine VanHise (HRC Fertility), who reviews its content and its IVF and IUI program, and reproductive epidemiologist Dr. Carmen Messerlian (founder of Vie Science, former Harvard T.H. Chan faculty).

Two published studies have tested Aviva exercise, both by the same Hungarian research group, both in women with painful periods (primary dysmenorrhea), not fertility. Both were small and not randomized: women chose whether to join the in-person, instructor-led exercise group (twice a week, 30 minutes) or the control group. In the 2024 study (78 women), menstrual pain dropped significantly more in the exercise group; the authors call the results preliminary. In the 2023 study (73 women), period pain did not differ between groups, and the uterine arteries'' pulsatility index rose more in the exercise group, which the authors read as reduced blood flow to the uterus from blood being redirected after exercise.

The brand says a pilot study in IVF patients has not been published and a larger controlled study is underway. ayna found no published study of the program''s effect on fertility, ovulation or pregnancy.', 'The brand''s testimonials page shares member stories of pregnancies, returned periods and less period pain. These are chosen by the brand. ayna found no independent reviews or ratings.', 'Per the brand, members report reduced PMS, more regular cycles and stronger fertility markers within one to three months. Published research on the Aviva Method is limited to two small, non-randomized studies on period pain; fertility outcomes haven''t been studied.', 'brand', 'The program''s medical advisor is reproductive endocrinologist Katherine VanHise, MD (HRC Fertility), and its scientific advisor is reproductive epidemiologist Carmen Messerlian, PhD, per the brand. The study summaries are ayna''s reading of the published papers.', 'curated', false, false, null, true, '{"platform":"Online, on-demand","affiliateUrl":"https://myclass.thefertilityclass.com/a/2148088258/fLawFjD7","gallery":["/products/fertility-class/group-class.webp","/products/fertility-class/founders.webp"],"ingredients":"Not a physical product: see \"How it works\" below for what the membership includes.","doctorOpinionShort":"Advised by a reproductive endocrinologist, per the brand. Two small, non-randomized studies of Aviva exercise looked at period pain (one found less pain, one didn''t); none has tested fertility.","doctorOpinionCitations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/38276063/","label":"PubMed: Kovács et al. 2024, Aviva exercise and pain in primary dysmenorrhea (78 women, non-randomized)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/38002635/","label":"PubMed: Kovács et al. 2023, exercise and uterine artery pulsatility index in primary dysmenorrhea (73 women, non-randomized)"}],"whoItsFor":["Women trying to conceive, naturally or with IVF or IUI, who want a gentle movement practice alongside their care (per the brand)","Women with irregular, absent or painful periods, or PCOS, who want a guided at-home routine (per the brand)","People who want short, low-impact, no-equipment classes they can do at home"],"howToUse":{"intro":"Per The Fertility Class:","steps":["Start with the Foundations series to learn the exercise sequence, plus a one-on-one onboarding call with a certified instructor.","Practice 20 to 30 minute classes at home, matched to your cycle phase. If you aren''t cycling regularly, they guide you on another rhythm.","Each class has a warm-up, the signature sequence of deep abdominal and pelvic exercises, and a cool-down with stretching and breathwork. A mat is optional; some moves use a chair for balance.","If you''re having IVF or IUI, they recommend starting at least a month before a treatment cycle and following the phase-by-phase plan, which pauses some exercises during sensitive phases. Check with your fertility specialist first."],"sourceUrl":"https://www.thefertilityclass.com/faqs","sourceLabel":"thefertilityclass.com: FAQs"},"warnings":["Not recommended, per the brand, with a spinal hernia, extremely heavy periods (menorrhagia), active malignant tumors, uncontrolled prolapse, recent abdominal surgery without clearance, or an IUD in place.","With an endometriosis diagnosis, the brand requires a one-on-one session with an instructor before starting.","During IVF or IUI, check with your fertility clinic before starting or changing exercise."],"scientificCitations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/38276063/","text":"Kovács et al., Medicina 2024: The Effect of Aviva Exercise Intervention on Pain Level and Body Awareness in Women with Primary Dysmenorrhea","summary":"Prospective observational study, 78 women (40 exercise, 38 control), not randomized. Twice-weekly 30-minute Aviva exercise for two cycles. Menstrual pain fell significantly more in the exercise group (p < 0.001); body awareness did not differ. The authors call the results preliminary and say larger trials are needed. Studied period pain, not fertility."},{"url":"https://pubmed.ncbi.nlm.nih.gov/38002635/","text":"Kovács et al., J Clin Med 2023: The Effect of Exercise on Pulsatility Index of Uterine Arteries and Pain in Primary Dysmenorrhea","summary":"Same group, 73 women (38 exercise, 35 control), not randomized. The uterine artery pulsatility index rose more in the exercise group (p = 0.011), which the authors interpret as reduced uterine blood flow from redistribution after exercise. Period pain did not differ between groups."}],"verificationLinks":{"doctor":{"links":[{"url":"https://www.thefertilityclass.com/advisory-board-1","text":"thefertilityclass.com: Medical & Scientific Advisory Board","summary":"Dr. Katherine VanHise (reproductive endocrinologist, HRC Fertility) and Dr. Carmen Messerlian (reproductive epidemiologist)."}]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://www.thefertilityclass.com/testimonials","text":"thefertilityclass.com: Testimonials","summary":"Member stories chosen by the brand; no independent reviews found."},{"platform":"website","url":"https://www.thefertilityclass.com/studies","text":"thefertilityclass.com: Studies","summary":"The research the brand cites, including the two Aviva Method studies."},{"platform":"website","url":"https://thestoryexchange.org/a-course-focused-on-reproductive-health-and-wellness/","text":"The Story Exchange: interview with co-founder Zsofia Jamieson","summary":"Q&A with co-founder Zsofia Jamieson (May 2026). The Story Exchange named The Fertility Class to its 2026 list of 15 Brilliant Business Ideas."}]}},"integrations":[],"badges":["Female-Founded"],"isEmergingBrand":true}'::jsonb)
